"""Build unsigned CI or stably signed local macOS apps with locked dependencies."""

import json
import os
import plistlib
import time
from dataclasses import dataclass
from pathlib import Path

from . import signing
from .core.paths import ROOT
from .core.process import execute, run
from .engine import bundle
from .project import main as project
from .tools.swift import check_toolchain
from .tools.xcodebuild import application_path, build_job_arguments, isolated_build_settings, require_mcp_helper


BUNDLE_ID = signing.BUNDLE_ID
QUIT_TIMEOUT = 20
# Generated by XcodeGen from .xcodegen/macOS.yml, which always points the app target at it.
ENTITLEMENTS = ROOT / "Containers/macOS/Arx.entitlements"
# What only a provisioning profile can grant (DEV-1013).
PROVISIONED_ENTITLEMENTS = (
    "com.apple.developer.icloud-container-identifiers",
    "com.apple.developer.icloud-services",
    "com.apple.developer.icloud-container-environment",
    "com.apple.developer.aps-environment",
)


# Where signed builds (make run, make run-preview, make run-dev, the smokes) put the app. All three
# run variants build the same Debug product there, so each replaces the others' bundle.
SIGNED_DERIVED_DATA = ROOT / "build/DerivedData"
# make run-preview's own data: Chromium's folder, Arx's workspace and the Keychain item.
PREVIEW_DATA_FOLDER = signing.BUNDLE_ID + ".preview"


@dataclass(frozen=True)
class RunVariant:
    """A Debug build `make run`, `make run-preview` or `make run-dev` opens: its bundle ID, the
    xcodebuild settings that make it, and which running copies it quits first."""
    name: str
    bundle_id: str
    settings: tuple = ()
    # Shares the installed Arx's data folder, so the installed Arx has to quit first.
    uses_installed_data: bool = False

    def quitting(self):
        """(bundle ID, folder or None) pairs of the running copies to quit before building: every
        copy of an app sharing this one's data, and any copy run from the build folder, whose
        bundle the build replaces."""
        builds = str(SIGNED_DERIVED_DATA) + "/"
        targets = []
        for bundle_id in (signing.BUNDLE_ID, signing.DEV_BUNDLE_ID):
            owns_data = bundle_id == self.bundle_id and (self.uses_installed_data or bundle_id == signing.DEV_BUNDLE_ID)
            targets.append((bundle_id, None if owns_data else builds))
        return targets


# DEV-1013 made every Debug build Arx Dev. make run and make run-preview build Debug as Arx
# instead: the installed Arx's data, or a data folder of its own.
ARX_SETTINGS = (
    f"ARX_BUNDLE_ID={signing.BUNDLE_ID}",
    "ARX_DISPLAY_NAME=Arx",
    "ARX_APP_ICON=AppIcon",
    "ARX_STORAGE_KEY_SERVICE=Arx Storage Key",
    "ARX_STORAGE_KEY_ACCOUNT=Arx",
)
RUN_VARIANTS = {
    "live": RunVariant("live", signing.BUNDLE_ID, ARX_SETTINGS, uses_installed_data=True),
    "preview": RunVariant("preview", signing.BUNDLE_ID, (
        f"ARX_BUNDLE_ID={signing.BUNDLE_ID}",
        "ARX_DISPLAY_NAME=Arx Preview",
        "ARX_APP_ICON=AppIcon",
        f"ARX_DATA_FOLDER={PREVIEW_DATA_FOLDER}",
        "ARX_SUPPORT_NAME=Arx Preview",
        "ARX_STORAGE_KEY_SERVICE=Arx Preview Storage Key",
        "ARX_STORAGE_KEY_ACCOUNT=Arx Preview",
    )),
    "dev": RunVariant("dev", signing.DEV_BUNDLE_ID),
}


def configuration_name(configuration=None):
    return configuration or os.environ.get("CONFIGURATION", "Debug")


def running_arx(*, quitting=False, path=None, bundle_id=BUNDLE_ID, under=None):
    """Count running copies of the app with this bundle ID through AppKit, asking them to quit as
    if by Command-Q when told to. With a path, only the copy launched from that bundle counts;
    with `under`, only copies launched from inside that folder."""
    selection = (
        f"apps = apps.filter(app => !app.bundleURL.isNil() && app.bundleURL.path.js === {json.dumps(str(path))});"
        if path else ""
    )
    if under:
        selection += f"apps = apps.filter(app => !app.bundleURL.isNil() && app.bundleURL.path.js.startsWith({json.dumps(str(under))}));"

    action = "apps.forEach(app => app.terminate);" if quitting else ""
    script = (
        "ObjC.import('AppKit');"
        f"let apps = $.NSRunningApplication.runningApplicationsWithBundleIdentifier({json.dumps(bundle_id)}).js;"
        f"{selection}"
        f"{action}"
        "apps.length;"
    )
    return int(run(["osascript", "-l", "JavaScript", "-e", script], capture=True).strip())


def close_running_arx(bundle_id=None, *, variant=None):
    """Quits the running copies of the app this build replaces or shares data with: for a run
    variant, what `RunVariant.quitting` names (make run quits the installed Arx, make run-preview
    and make run-dev leave it open); otherwise the configuration's edition, Arx Dev for Debug."""
    if os.environ.get("ARX_KEEP_RUNNING") == "1":
        return
    if variant is None:
        targets = [(bundle_id or signing.bundle_id(configuration_name()), None)]
    else:
        targets = variant.quitting()

    def count(quitting=False):
        return sum(
            running_arx(quitting=quitting, bundle_id=target, **({"under": under} if under else {}))
            for target, under in targets
        )

    if not count(quitting=True):
        return
    deadline = time.monotonic() + QUIT_TIMEOUT
    while count():
        if time.monotonic() >= deadline:
            raise ValueError("Arx did not quit. Answer its prompt, or set ARX_KEEP_RUNNING=1 to leave it open.")
        time.sleep(0.5)


def drop_provisioned_entitlements(path=ENTITLEMENTS):
    """Removes what needs a provisioning profile from the generated entitlements, for this
    build only: every build generates the project, and with it the file, again first."""
    with path.open("rb") as file:
        entitlements = plistlib.load(file)
    for key in PROVISIONED_ENTITLEMENTS:
        entitlements.pop(key, None)
    path.write_bytes(plistlib.dumps(entitlements))


def signed_settings(configuration=None, *, require_profile=False, bundle_id=None):
    """Manual Apple Development signing, and whether the app gets a provisioning profile. Xcode
    embeds the matching profile as Contents/embedded.provisionprofile in the app before signing
    it; only the app target reads ARX_PROVISIONING_PROFILE, so the bundled helpers stay
    profile-free.

    Until Arx Dev's profile exists (DEV-1013), a Debug build is signed without one, and main()
    drops iCloud and push from its entitlements, unless the build needs them (require_profile)."""
    identity = signing.identity()
    bundle_id = bundle_id or signing.bundle_id(configuration_name(configuration))
    settings = [
        "CODE_SIGNING_ALLOWED=YES", "CODE_SIGN_STYLE=Manual",
        f"CODE_SIGN_IDENTITY={identity}",
        f"DEVELOPMENT_TEAM={signing.team()}",
    ]
    optional = bundle_id == signing.DEV_BUNDLE_ID and not require_profile
    profile = signing.dev_profile(identity) if optional else signing.profile(signing.DEVELOPMENT, identity, bundle_id)
    if profile is None:
        print(signing.NO_DEV_PROFILE.format(name=signing.profile_name(signing.DEVELOPMENT, bundle_id)), flush=True)
        return [*settings, "ARX_PROVISIONING_PROFILE="], False
    signing.install_for_xcode(profile)
    return [
        *settings,
        f"ARX_PROVISIONING_PROFILE={profile.uuid}",
        f"ARX_ICLOUD_ENVIRONMENT={profile.icloud_environment}",
        f"ARX_APS_ENVIRONMENT={profile.aps_environment}",
    ], True


def prepare():
    check_toolchain()
    project()
    lockfile = ROOT / "Package.resolved"
    if not lockfile.is_file():
        raise ValueError("Missing Package.resolved. Run make resolve before building the app.")
    workspace_lockfile = ROOT / "Project.xcworkspace/xcshareddata/swiftpm/Package.resolved"
    workspace_lockfile.parent.mkdir(parents=True, exist_ok=True)
    workspace_lockfile.write_bytes(lockfile.read_bytes())


def main(scheme="Arx", log="build-app.log", *, signed=False, require_engine=False, require_profile=False, configuration=None, derived_data=None, build_settings=(), bundle_id=None):
    jobs = build_job_arguments()
    require_engine = require_engine or (scheme == "Arx" and os.environ.get("ARX_REQUIRE_ENGINE") == "1")
    if require_engine:
        bundle.require()
    signing_settings, provisioned = signed_settings(configuration, require_profile=require_profile, bundle_id=bundle_id) if signed else (["CODE_SIGNING_ALLOWED=NO"], False)
    unsigned_arx = not signed and scheme == "Arx"
    derived_data = derived_data or ROOT / "build" / ("UnsignedDerivedData" if unsigned_arx else "DerivedData")
    prepare()
    if signed and not provisioned and scheme == "Arx":
        drop_provisioned_entitlements()
    arguments = [
        "xcodebuild", "-workspace", "Project.xcworkspace", "-scheme", scheme,
        "-configuration", configuration_name(configuration),
        "-destination", os.environ.get("DESTINATION", "platform=macOS"),
        "-derivedDataPath", str(derived_data),
        "-clonedSourcePackagesDirPath", str(ROOT / ".build"),
        "-onlyUsePackageVersionsFromResolvedFile",
        *jobs,
        *signing_settings,
        *(isolated_build_settings(derived_data) if unsigned_arx else []),
        *(["ARX_REQUIRE_ENGINE=1"] if require_engine else []),
        *build_settings,
    ]
    run([*arguments, "build"], log=log)
    settings = run([*arguments, "-showBuildSettings", "-json"], capture=True)
    app = application_path(settings, scheme)
    if scheme == "Arx":
        require_mcp_helper(app)
        if provisioned and not (Path(app) / "Contents/embedded.provisionprofile").is_file():
            raise ValueError(f"The signed app has no embedded provisioning profile: {app}")
    if require_engine:
        bundle.validate_application(app)
    print(f"Application: {app}", flush=True)
    return app


def signed(**options):
    return main(log="build-app-signed.log", signed=True, **options)


def runtime():
    return main(log="build-app-runtime.log", require_engine=True)


def launch(variant="live"):
    """make run (live): Debug as Arx, on the installed Arx's data, which quits first.
    make run-preview (preview): Debug as Arx Preview, with its own data folder and Keychain item.
    make run-dev (dev): Arx Dev, as every Debug build was before (DEV-1013)."""
    selected = RUN_VARIANTS[variant]
    # Before the build, which replaces the bundle a running copy is using.
    close_running_arx(variant=selected)
    options = {} if selected.name == "dev" else {
        "configuration": "Debug", "bundle_id": selected.bundle_id, "build_settings": selected.settings,
    }
    app = signed(**options)
    run(["open", str(app)])


def launch_preview():
    launch("preview")


def launch_dev():
    launch("dev")


if __name__ == "__main__":
    raise SystemExit(execute(main))
